"use client";
/* Pinch, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Pinch(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("pinch"); }, []);
  return React.createElement("piix-pal", { "pal": "pinch", ...piixAttrs(props) });
}

export default Pinch;
